import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("A vendor name already used in my tenant is refused, ignoring case", { tag: "@VEN-03" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const existingName = uniqueName("Acme Freight");
  const existing = await factory.vendor({ as: "member", name: existingName, category: "logistics" });

  // Act
  const response = await member.post("/api/vendors", {
    data: {
      name: existingName.toLowerCase(),
      category: "logistics",
      contact_email: "ops@acmefreight.example",
    },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");

  // Re-read the stored list: the refused create must not have added a second record.
  const listed = await expectStatus<{ items: { id: string; name: string }[]; total: number }>(
    await member.get("/api/vendors", { params: { q: existingName } }),
    200,
  );
  const matches = listed.items.filter((v) => v.name.toLowerCase() === existingName.toLowerCase());
  expect(matches.map((v) => v.id)).toEqual([existing.id]);
});
